// --- §describe ------------------------------------------------------------

func TestGoldenDescribe(t *testing.T) {
	g := vsSection(t, "describe")

	skipped := NewSealResult()
	skipped.SkippedReason = "x"
	failed := NewSealResult()
	failed.Error = "boom"
	failedSealed := NewSealResult()
	failedSealed.Error, failedSealed.Sealed = "boom", true
	resyncFull := NewSealResult()
	resyncFull.Sealed, resyncFull.Pushed = true, false
	resyncFull.FilesDeleted, resyncFull.FilesAdded = 2, 1
	resyncFull.CommitSha, resyncFull.RepoName = "abc1234", "o/r"
	resyncFull.CommitMessage = "resync: mirror follows the vault — 2 file(s) " +
		"deleted, 1 added/updated"
	resyncPushed := NewSealResult()
	resyncPushed.Sealed, resyncPushed.Pushed = true, true
	resyncPushed.CommitSha, resyncPushed.RepoName = "abc1234", "o/r"
	resyncPushed.CommitMessage = "resync: mirror follows the vault"
	sealedFull := NewSealResult()
	sealedFull.Sealed, sealedFull.Pushed, sealedFull.FilesChanged = true, true, 5
	sealedFull.CommitSha, sealedFull.RepoName = "abc1234", "o/r"
	sealedMinimal := NewSealResult()
	sealedMinimal.Sealed, sealedMinimal.FilesChanged = true, 5

	got := map[string]string{
		"skipped":        skipped.Describe(),
		"failed":         failed.Describe(),
		"failed_sealed":  failedSealed.Describe(),
		"resync_full":    resyncFull.Describe(),
		"resync_pushed":  resyncPushed.Describe(),
		"sealed_full":    sealedFull.Describe(),
		"sealed_minimal": sealedMinimal.Describe(),
	}
	cmpVSGolden(t, "describe", got, g)
}

// --- §to_dict + ok -------------------------------------------------------

func TestGoldenToDict(t *testing.T) {
	g := vsSection(t, "to_dict")
	full := NewSealResult()
	full.Sealed, full.Pushed, full.FilesChanged = true, true, 7
	full.CommitSha = "abc1234"
	full.CommitMessage = "seal: vault snapshot — x"
	full.RepoName, full.RepoURL = "o/r", "https://github.com/o/r"
	full.FilesAdded, full.FilesDeleted, full.DurationMS = 2, 1, 12
	empty := NewSealResult()

	cmpVSGolden(t, "to_dict.full", plainMap(full.ToMap()), g["full"])
	cmpVSGolden(t, "to_dict.empty", plainMap(empty.ToMap()), g["empty"])

	okCases := map[string]bool{
		"plain_ok":     empty.OK(),
		"skipped_ok":   func() bool { r := NewSealResult(); r.SkippedReason = "x"; return r.OK() }(),
		"error_not_ok": func() bool { r := NewSealResult(); r.Error = "e"; return r.OK() }(),
		"sealed_ok":    func() bool { r := NewSealResult(); r.Sealed = true; return r.OK() }(),
	}
	cmpVSGolden(t, "to_dict.ok_laws", okCases, g["ok_laws"])
}

func plainMap(m *storage.OrderedMap) map[string]any {
	out := map[string]any{}
	for _, k := range m.Keys() {
		v, _ := m.Get(k)
		out[k] = v
	}
	return out
}

