// --- §owner_login (the 401 hint) -------------------------------------------

func TestGoldenOwnerLogin(t *testing.T) {
	g := vsSection(t, "owner_login")
	capture := func(status int, payload map[string]any) any {
		var logs [][2]string
		s := NewVaultSeal("/v", "tok", "r", true, true, 0,
			func(msg, level string) { logs = append(logs, [2]string{level, msg}) },
			false, nil)
		s.apiFn = func(string, string, map[string]any) (int, map[string]any) {
			return status, payload
		}
		login := s.ownerLogin()
		loginV := any(nil)
		if login != "" {
			loginV = login
		}
		logList := make([]any, len(logs))
		for i, l := range logs {
			logList[i] = []any{l[0], l[1]}
		}
		return []any{loginV, logList}
	}
	got := map[string]any{
		"good":         capture(200, map[string]any{"login": "testuser"}),
		"empty_login":  capture(200, map[string]any{"login": ""}),
		"unauthorized": capture(401, map[string]any{"message": "Bad credentials"}),
		"server_error": capture(500, map[string]any{"message": "oops"}),
		"network":      capture(0, map[string]any{"message": "timed out"}),
	}
	cmpVSGolden(t, "owner_login", got, g)
}

// --- §creation_guard --------------------------------------------------------

func TestGoldenCreationGuard(t *testing.T) {
	frozenGitDates(t)
	g := vsSection(t, "creation_guard")

	guard := func(repoName string, allowCreate bool, table map[[2]string][2]any) any {
		tmp := t.TempDir()
		s := NewVaultSeal(tmp, "tok", repoName, true, true, 0, nil, allowCreate, nil)
		calls := fakeAPI(s, table)
		ok, err := s.ensureRepo()
		errV := any(err)
		if err == "" {
			errV = nil
		}
		return map[string]any{
			"ok":    ok,
			"err":   errV,
			"calls": foldAny(tmp, *calls),
		}
	}

	mk := func(status int, payload map[string]any) [2]any {
		return [2]any{status, payload}
	}
	got := map[string]any{
		"no_opt_in": guard("my-vault-bak", false, map[[2]string][2]any{
			{"GET", "/user"}:                        mk(200, map[string]any{"login": "testuser"}),
			{"GET", "/repos/testuser/my-vault-bak"}: mk(404, map[string]any{"message": "Not Found"}),
		}),
		"allow_create": guard("my-vault-bak", true, map[[2]string][2]any{
			{"GET", "/user"}:                        mk(200, map[string]any{"login": "testuser"}),
			{"GET", "/repos/testuser/my-vault-bak"}: mk(404, map[string]any{"message": "Not Found"}),
			{"POST", "/user/repos"}:                 mk(201, map[string]any{"full_name": "testuser/my-vault-bak"}),
		}),
		"empty_name": guard("", false, nil),
		"existing": guard("my-vault-bak", false, map[[2]string][2]any{
			{"GET", "/user"}:                        mk(200, map[string]any{"login": "testuser"}),
			{"GET", "/repos/testuser/my-vault-bak"}: mk(200, map[string]any{"private": true}),
		}),
		"api_error": guard("my-vault-bak", false, map[[2]string][2]any{
			{"GET", "/user"}:                        mk(200, map[string]any{"login": "testuser"}),
			{"GET", "/repos/testuser/my-vault-bak"}: mk(403, map[string]any{"message": "nope"}),
		}),
		"create_race_422": guard("my-vault-bak", true, map[[2]string][2]any{
			{"GET", "/user"}:                        mk(200, map[string]any{"login": "testuser"}),
			{"GET", "/repos/testuser/my-vault-bak"}: mk(404, map[string]any{"message": "Not Found"}),
			{"POST", "/user/repos"}:                 mk(422, map[string]any{"message": "name already exists"}),
		}),
	}
	// the ensureRepo branch runs real git init on the temp vault —
	// nothing path-shaped rides the captured facts (the err strings
	// name owner/repo, not paths).
	cmpVSGolden(t, "creation_guard", got, g)
}

// --- §gitignore_merge --------------------------------------------------------

func TestGoldenGitignoreMerge(t *testing.T) {
	g := vsSection(t, "gitignore_merge")

	vault := t.TempDir()
	s := NewVaultSeal(vault, "", "r", false, true, 0, nil, false, nil)
	added := s.EnsureGitignore()
	giPath := filepath.Join(vault, ".gitignore")

	got := map[string]any{
		"fresh_added": added,
		"fresh_text":  readText(t, giPath),
	}
	// existing user rules + idempotence
	appendFile(t, giPath, "user-rule/\n")
	got["user_added"] = s.EnsureGitignore()
	got["user_text"] = readText(t, giPath)
	got["idempotent_added"] = s.EnsureGitignore()
	got["idempotent_text"] = readText(t, giPath)

	// the CRLF tail quirk: current.rstrip("\n") keeps the \r
	vault2 := t.TempDir()
	gi2 := filepath.Join(vault2, ".gitignore")
	writeFile(t, gi2, "user\r\n")
	s2 := NewVaultSeal(vault2, "", "r", false, true, 0, nil, false, nil)
	s2.EnsureGitignore()
	got["crlf_text"] = readText(t, gi2)

	cmpVSGolden(t, "gitignore_merge", got, g)
}

func readText(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

func appendFile(t *testing.T, path, text string) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := f.WriteString(text); err != nil {
		t.Fatal(err)
	}
	f.Close()
}

