// diskFiles mirrors the generator's walk: every file under the vault
// except the .git tree and the .git* names, sorted, POSIX-shaped.
func diskFiles(t *testing.T, vault string) []string {
	t.Helper()
	var out []string
	err := filepath.Walk(vault, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		rel := filepath.ToSlash(strings.TrimPrefix(strings.TrimPrefix(path, vault), "/"))
		if info.IsDir() {
			if rel == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasPrefix(info.Name(), ".git") {
			return nil
		}
		out = append(out, rel)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	sort.Strings(out)
	return out
}

// --- §delta_counts --------------------------------------------------------------

func TestGoldenDeltaCounts(t *testing.T) {
	frozenGitDates(t)
	g := vsSection(t, "delta_counts")
	vault := t.TempDir()
	runGit(t, vault, "init", "-q", "-b", "main")
	runGit(t, vault, "config", "user.email", "t@example.com")
	runGit(t, vault, "config", "user.name", "T")
	writeFile(t, filepath.Join(vault, "a.md"), "one")
	writeFile(t, filepath.Join(vault, "b.md"), "two")
	runGit(t, vault, "add", "-A")
	runGit(t, vault, "commit", "-qm", "first")
	os.Remove(filepath.Join(vault, "b.md"))
	writeFile(t, filepath.Join(vault, "a.md"), "one changed")
	writeFile(t, filepath.Join(vault, "c.md"), "three")
	runGit(t, vault, "add", "-A")
	runGit(t, vault, "commit", "-qm", "second")
	s := NewVaultSeal(vault, "tok", "r", false, true, 0, nil, false, nil)
	a, d, tot := s.deltaCounts("HEAD", "HEAD~1")
	got := map[string]any{
		"head_to_head1": []int{a, d, tot},
	}
	a, d, tot = s.deltaCounts("HEAD~1", "HEAD")
	got["head1_to_head"] = []int{a, d, tot}
	a, d, tot = s.deltaCounts("HEAD", "HEAD")
	got["self"] = []int{a, d, tot}
	a, d, tot = s.deltaCounts("no-such-ref", "HEAD")
	got["junk_ref"] = []int{a, d, tot}
	cmpVSGolden(t, "delta_counts", got, g)
}

// --- §fnmatch --------------------------------------------------------------------

func TestGoldenFnMatch(t *testing.T) {
	g := loadVSGolden(t)
	rows, ok := g["fnmatch"].([]any)
	if !ok {
		t.Fatal("golden section fnmatch missing")
	}
	for _, row := range rows {
		c, ok := row.([]any)
		if !ok || len(c) != 3 {
			t.Fatalf("fnmatch row shape: %v", row)
		}
		name, _ := c[0].(string)
		pat, _ := c[1].(string)
		want, _ := c[2].(bool)
		if got := FnMatch(name, pat); got != want {
			t.Errorf("FnMatch(%q, %q) = %v, want %v", name, pat, got, want)
		}
	}
}

