func TestGoldenStatus(t *testing.T) {
	frozenGitDates(t)
	g := vsSection(t, "status")
	tmp := t.TempDir()
	vault := filepath.Join(tmp, "vault")
	if err := os.MkdirAll(vault, 0o755); err != nil {
		t.Fatal(err)
	}
	runGit(t, vault, "init", "-q", "-b", "main")
	runGit(t, vault, "config", "user.email", "t@example.com")
	runGit(t, vault, "config", "user.name", "T")
	writeFile(t, filepath.Join(vault, "note.md"), "content\n")
	runGit(t, vault, "add", "-A")
	runGit(t, vault, "commit", "-qm", "the base commit")
	s := NewVaultSeal(vault, "tok", "mirror", true, true, 0, nil, false, nil)
	clean := plainMap(s.Status())
	writeFile(t, filepath.Join(vault, "dirty.md"), "uncommitted\n")
	dirty := plainMap(s.Status())

	noVault := NewVaultSeal("", "", "", false, true, 0, nil, false, nil)
	missing := plainMap(NewVaultSeal(filepath.Join(tmp, "nope"), "tok", "m",
		false, true, 0, nil, false, nil).Status())
	missing["vault_path"] = "<vault>/nope" // the generator's fold
	got := map[string]any{
		"clean":         clean,
		"dirty":         dirty,
		"no_vault":      plainMap(noVault.Status()),
		"missing_vault": missing,
	}
	cmpVSGolden(t, "status", foldAny(vault, got), g)
}

